<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { t, formatNumber } from '../i18n'
import { sprintWeightRoles, sprintWeightBreakdown, sprintWeightCoverage, type SprintWeightSummary } from '../sprintWeights'
import RequirementCode from './RequirementCode.vue'

const props = defineProps<{ summary?: SprintWeightSummary | null; loading?: boolean; error?: string; backlog?: boolean; projectId?:string; members?:{id:string;name:string}[] }>()
const emit = defineEmits<{ (event: 'refresh'): void; (event:'open-requirement',requirement:any):void }>()
const query = ref('')
const page = ref(1)
const pageSize = 30
const breakdown = computed(() => props.summary ? sprintWeightBreakdown(props.summary) : [])
const coverage = computed(() => props.summary ? sprintWeightCoverage(props.summary) : 0)
const filtered = computed(() => (props.summary?.items || []).filter(item => !query.value.trim() || `${item.code} ${item.title}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize)))
const visible = computed(() => filtered.value.slice((page.value - 1) * pageSize, page.value * pageSize))
const number = (value: number) => formatNumber(value, { maximumFractionDigits: 6 })
watch(query, () => { page.value = 1 })
watch(pages,value=>{page.value=Math.min(page.value,value)})
</script>

<template>
  <section class="sprint-weights" :aria-label="t('迭代权重统计')">
    <header class="weights-heading"><div><span class="eyebrow">{{ t('需求难度评估') }}</span><h2>{{ backlog ? t('待规划权重') : t('迭代权重统计') }}</h2><p>{{ t('五项职能难度直接相加，与需求中的手填权重保持一致。') }}</p></div><button class="btn compact" :disabled="loading" @click="emit('refresh')">{{ t('刷新统计') }}</button></header>
    <div v-if="loading" class="weight-state" role="status"><span class="spinner"></span>{{ t('正在汇总权重…') }}</div>
    <div v-else-if="error || !summary" class="weight-state" role="alert"><b>{{ t('权重统计暂不可用') }}</b><p>{{ error ? t(error) : t('请刷新以获取当前迭代的完整权重。') }}</p><button class="btn" @click="emit('refresh')">{{ t('重试') }}</button></div>
    <template v-else>
      <div class="weight-metrics"><article class="weight-grand-total"><span>{{ t('总权重') }}</span><output :aria-label="t('总权重')">{{ number(summary.totalWeight) }}</output><small>{{ t('权重不是工时，不包含缺陷') }}</small></article><article><span>{{ t('需求数') }}</span><b>{{ formatNumber(summary.requirementCount) }}</b><small>{{ t('当前归属 · 全部状态') }}</small></article><article><span>{{ t('已估算需求') }}</span><b>{{ formatNumber(summary.estimatedCount) }}<em>/ {{ formatNumber(summary.requirementCount) }}</em></b><small>{{ t('估算覆盖率 {percent}%', { percent: coverage }) }}</small></article><article><span>{{ t('未估算需求') }}</span><b>{{ formatNumber(summary.unestimatedCount) }}</b><small>{{ t('所有职能均未填写，按 0 计') }}</small></article></div>
      <div class="weight-analysis"><article class="weight-breakdown"><header><h3>{{ t('职能权重分布') }}</h3><span>{{ t('数值 / 占总权重') }}</span></header><div v-for="role in breakdown" :key="role.key" class="weight-dimension"><div class="dimension-label"><i :style="{ background: role.color }"></i><b>{{ t(role.label) }}</b><small>{{ t('{count} 条已填写', { count: role.estimatedCount }) }}</small></div><div class="dimension-bar" role="meter" :aria-label="t('{role}权重占比', { role: t(role.label) })" :aria-valuenow="role.percent" aria-valuemin="0" aria-valuemax="100"><i :style="{ width: `${role.percent}%`, background: role.color }"></i></div><div class="dimension-value"><b>{{ number(role.total) }}</b><span>{{ formatNumber(role.percent, { maximumFractionDigits: 1 }) }}%</span></div></div></article><aside class="weight-method"><span class="method-symbol" aria-hidden="true">∑</span><h3>{{ t('统计口径') }}</h3><p>{{ t('统计当前项目、当前迭代的全部需求，包含已完成、已拒绝和已取消的需求，不受列表分页影响。') }}</p><p>{{ t('任一职能填写数值即为已估算，手动填写 0 也计入；绑定人员但未填写数值不算估算。') }}</p><p>{{ t('父子需求各自手填值仅计一次，不额外汇总或继承子需求权重。') }}</p><small>{{ t('按原始数值累加后保留最多 6 位小数；明细显示的舍入总和可能有末位差异。') }}</small></aside></div>
      <section class="weight-detail"><header><div><h3>{{ t('需求权重明细') }}</h3><p>{{ t('核对每条需求的职能难度，点击编号返回需求。') }}</p></div><input v-model="query" type="search" :aria-label="t('搜索权重明细')" :placeholder="t('搜索编号或标题')"></header><div class="weight-table-wrap"><table><thead><tr><th>{{ t('需求') }}</th><th>{{ t('状态') }}</th><th v-for="role in sprintWeightRoles" :key="role.key">{{ t(role.label) }}</th><th>{{ t('总权重') }}</th><th>{{ t('估算情况') }}</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td><RequirementCode :requirement="item" :project-id="projectId" :members="members" @open="emit('open-requirement',{...item,objectType:'requirement'})"/><button class="weight-item-title" type="button" @click="emit('open-requirement',{...item,objectType:'requirement'})">{{item.title}}</button><small v-if="item.parentId">{{ t('子需求 · 仅自身权重') }}</small></td><td><span :class="['status', item.status]">{{ t(item.status) }}</span></td><td v-for="role in sprintWeightRoles" :key="role.key" class="weight-number">{{ item.weights[role.key] === null ? '—' : number(item.weights[role.key]!) }}</td><td class="weight-number total-column">{{ number(item.totalWeight) }}</td><td><span :class="['estimate-mark', { missing: !item.estimated }]">{{ item.estimated ? t('已估算') : t('未估算') }}</span></td></tr><tr v-if="!visible.length"><td colspan="9" class="weight-empty"><b>{{ summary.requirementCount ? t('没有匹配的权重明细') : t('当前没有需求可统计') }}</b><p>{{ summary.requirementCount ? t('清除搜索后可查看完整明细，顶部总计不受搜索影响。') : t('将需求加入当前迭代并填写难度后，统计会显示在这里。') }}</p></td></tr></tbody></table></div><footer><span>{{ t('{count} 条需求 · — 表示未填写', { count: filtered.length }) }}</span><div><button class="btn compact" :disabled="page <= 1" :aria-label="t('上一页')" @click="page--">‹</button><span>{{ page }} / {{ pages }}</span><button class="btn compact" :disabled="page >= pages" :aria-label="t('下一页')" @click="page++">›</button></div></footer></section>
    </template>
  </section>
</template>

<style scoped>
