en}.dimension-bar>i{display:block;height:100%;border-radius:4px;transition:width .25s}.dimension-value{display:flex;justify-content:flex-end;align-items:baseline;gap:9px;font-variant-numeric:tabular-nums}.dimension-value>b{font-size:14px;color:#3a435b}.dimension-value>span{font-size:10px;color:#969eac;min-width:34px;text-align:right}.weight-method{background:#fafbfe}.method-symbol{width:33px;height:33px;display:grid;place-items:center;border-radius:9px;background:#eeecfc;color:#776fd1;font-size:24px;margin-bottom:15px}.weight-method p{font-size:12px;line-height:1.85;color:#778097;margin:11px 0}.weight-method small{display:block;font-size:10px;line-height:1.75;color:#9aa2b0;padding-top:10px;border-top:1px dashed #e1e4ec}.weight-detail{padding:0;overflow:hidden}.weight-detail>header{padding:20px 22px}.weight-detail input{border:1px solid #e1e5ed;border-radius:7px;padding:9px 11px;font-size:12px;width:210px}.weight-table-wrap{overflow-x:auto}.weight-detail table{width:100%;border-collapse:collapse;font-size:12px}.weight-detail th{background:#f8f9fc;color:#818b9c;font-weight:500;text-align:left;padding:12px 14px;white-space:nowrap;border-block:1px solid #edf0f5}.weight-detail td{padding:13px 14px;border-bottom:1px solid #f0f2f6;white-space:nowrap;color:#646d83}.weight-detail td:first-child{min-width:240px;max-width:360px;white-space:normal}.weight-detail td:first-child a{font-size:10px;color:#7770d8;text-decoration:none}.weight-detail td:first-child a:hover{text-decoration:underline}.weight-detail td:first-child>b{display:block;color:#404a63;font-weight:500;line-height:1.6;margin:4px 0}.weight-detail td:first-child small{font-size:10px;color:#98a1b0}.weight-number{font-variant-numeric:tabular-nums;text-align:right}.weight-detail .total-column{color:#6b65d5;font-weight:650;background:#faf9ff}.estimate-mark{font-size:10px;color:#3a9876;background:#ecf7f1;padding:4px 7px;border-radius:5px}.estimate-mark.missing{color:#a2937d;background:#f7f4ed}.weight-detail>footer{display:flex;align-items:center;justify-content:space-between;padding:15px 22px;font-size:11px;color:#9199a8}.weight-detail>footer>div{display:flex;align-items:center;gap:12px}.weight-state,.weight-empty{text-align:center;padding:40px;color:#8b94a6;font-size:13px}.weight-state{border:1px dashed #dce1eb;border-radius:12px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px}.weight-empty p{margin-top:10px}.weight-detail .weight-empty{padding:36px;white-space:normal}@media(max-width:1000px){.weight-analysis{grid-template-columns:1fr}.weight-metrics{grid-template-columns:repeat(2,1fr)}.weight-method{padding:18px}}@media(max-width:650px){.weights-heading,.weight-detail>header{align-items:flex-start;flex-direction:column}.weight-metrics{gap:8px}.weight-metrics article{padding:14px}.weight-dimension{grid-template-columns:95px 1fr 85px;gap:9px}.weight-breakdown{padding:14px}.weight-metrics article>b,.weight-metrics output{font-size:25px}}
</style>
